fn solve(w: i8, a: i8, b: i8) -> i8 {
    // Compute the absolute distance between the two left endpoints
    let dist = (a - b).abs();

    // If they already touch or overlap, no shift is needed
    if dist <= w {
        0
    } else {
        // Otherwise shift by the gap beyond width w
        dist - w
    }
}

